<script lang="ts">
 import { page } from '$app/state'; import { goto, invalidateAll } from '$app/navigation';
 import { LayoutDashboard, BedDouble, CalendarDays, ClipboardList, FileHeart, ReceiptText, LogOut, Bell, Menu, X, ChevronRight, Search } from 'lucide-svelte';
 import { api } from '$lib/api'; import type { LayoutData } from './$types';
 let { data, children }: {data:LayoutData;children:import('svelte').Snippet}=$props();
 let mobileOpen=$state(false);let notificationsOpen=$state(false);let notifications=$state<{id:string;message:string;readAt:string|null;createdAt:string}[]>([]);let notificationError=$state('');let loggingOut=$state(false);let patientSearch=$state('');
 const navigation=[{path:'/dashboard',label:'Dashboard Siklus',icon:LayoutDashboard,roles:['DOKTER','PERAWAT']},{path:'/rooms',label:'Manajemen Ruangan',icon:BedDouble,roles:['PERAWAT','ADMISI']},{path:'/calendar',label:'Kalender Ruangan',icon:CalendarDays,roles:['PERAWAT','DOKTER','ADMISI']},{path:'/medical-records',label:'Rekam Medis',icon:FileHeart,roles:['DOKTER','PERAWAT']},{path:'/tasks',label:'Tugas Perawatan',icon:ClipboardList,roles:['PERAWAT']},{path:'/invoices',label:'Tagihan',icon:ReceiptText,roles:['ADMISI']}];
 let current=$derived(navigation.find(n=>page.url.pathname.startsWith(n.path))?.label??'Ringkasan Pasien');
 let role=$derived(data.user.coordinator?'Koordinator Perawat':({DOKTER:'Dokter',PERAWAT:'Perawat',ADMISI:'Admisi'}[data.user.role]));
 async function logout(){loggingOut=true;try{await api('/session',{method:'DELETE'});await goto('/login',{invalidateAll:true});}catch{loggingOut=false;}}
 async function showNotifications(){notificationsOpen=!notificationsOpen;if(!notificationsOpen)return;try{const result=await api<{items:typeof notifications}>('/notifications');notifications=result.items;notificationError='';}catch(error){notificationError=(error as Error).message;}}
 async function readNotification(id:string){try{await api(`/notifications/${id}/read`,{method:'POST',body:'{}'});notifications=notifications.map(n=>n.id===id?{...n,readAt:new Date().toISOString()}:n);}catch(error){notificationError=(error as Error).message;}}
</script>
<svelte:head><title>{current} · InpaCare</title><meta name="description" content="InpaCare — sistem rawat inap terhubung."/></svelte:head>
<a class="skip-link" href="#main-content">Lewati navigasi</a>
{#if mobileOpen}<button class="sidebar-backdrop" aria-label="Tutup navigasi" onclick={()=>mobileOpen=false}></button>{/if}
<aside class:open={mobileOpen} class="sidebar">
 <a class="brand" href={data.user.role==='ADMISI'?'/invoices':'/dashboard'}>RSI<span>InpaCare</span></a>
 <div class="sidebar-kicker">SISTEM RAWAT INAP</div><div class="sidebar-divider"></div><div class="sidebar-kicker">RUANG KERJA</div><p class="workspace-name">Rawat inap</p>
 <nav aria-label="Navigasi utama">{#each navigation.filter(n=>n.roles.includes(data.user.role)) as item}<a class:active={page.url.pathname.startsWith(item.path)} href={item.path} onclick={()=>mobileOpen=false}><item.icon size={16} strokeWidth={1.6}/>{item.label}</a>{/each}</nav>
 <div class="sidebar-bottom"><button class="logout" onclick={logout} disabled={loggingOut}><LogOut size={15}/>{loggingOut?'Keluar…':'Keluar'}</button><div class="sidebar-divider"></div><strong>{role}</strong><span>{data.user.name}</span><span class="demo-tag">Data demo sintetis</span></div>
</aside>
<div class="app-body"><header class="topbar"><div class="breadcrumbs"><button class="icon-button menu-toggle" aria-label="Buka navigasi" onclick={()=>mobileOpen=true}><Menu size={21}/></button><span>Rawat Inap</span><ChevronRight size={12}/><span>{current}</span></div><div class="topbar-actions"><time>{new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date())}</time><button class="icon-button" aria-label="Notifikasi" aria-expanded={notificationsOpen} onclick={showNotifications}><Bell size={18}/></button><div class="avatar" title={data.user.name}>{data.user.name.replace(/^dr\. /,'').split(' ').map(n=>n[0]).slice(0,2).join('')}</div></div></header>
 {#if notificationsOpen}<section class="notifications" aria-label="Notifikasi"><div class="panel-header"><h2>Notifikasi</h2><button class="icon-button" aria-label="Tutup notifikasi" onclick={()=>notificationsOpen=false}><X size={18}/></button></div>{#if notificationError}<p class="error" role="alert">{notificationError}</p>{:else if notifications.length===0}<p class="empty">Belum ada notifikasi.</p>{:else}{#each notifications as notice}<button class:unread={!notice.readAt} class="notification" onclick={()=>readNotification(notice.id)}><span>{notice.message}</span><small>{new Date(notice.createdAt).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</small></button>{/each}{/if}</section>{/if}
 <main id="main-content">{@render children()}</main><footer class="app-footer"><span>InpaCare</span><span>Lingkungan demonstrasi · data sintetis</span></footer>
</div>
<style>
 .skip-link{position:fixed;top:-60px;left:240px;z-index:100;background:#fff;padding:12px}.skip-link:focus{top:8px}.sidebar{position:fixed;inset:0 auto 0 0;width:220px;background:#fff;display:flex;flex-direction:column;padding:25px 24px 20px;z-index:40;border-right:1px solid #edf0f4}.brand{font-size:27px;letter-spacing:-1.5px;color:#4e61f6;font-weight:750;display:flex;align-items:center;gap:10px;margin-bottom:30px}.brand span{font-size:12px;letter-spacing:0;font-weight:600;color:#9aa3b7}.sidebar-kicker{font-size:10px;letter-spacing:.6px;color:#818a9c}.sidebar-divider{height:1px;background:#edf0f4;margin:19px 0}.workspace-name{font-size:12px;margin:20px 0 17px;color:#667085}nav{display:flex;flex-direction:column;gap:7px;margin:0 -8px}nav a{display:flex;align-items:center;gap:11px;padding:13px 12px;font-size:12px;color:#626a7d;border-radius:8px;white-space:nowrap}nav a:hover{background:#f7f8fc}nav a.active{background:#eef0ff;color:#4e61f6;font-weight:650}.sidebar-bottom{margin-top:auto;display:flex;flex-direction:column;font-size:11px;gap:5px}.sidebar-bottom strong{font-size:12px}.sidebar-bottom span{color:#838b9b}.logout{padding:12px 0;display:flex;align-items:center;gap:10px;border:0;background:none;color:#818a9b;font-size:12px;text-align:left}.sidebar-bottom .sidebar-divider{margin:0 0 8px}.sidebar-bottom .demo-tag{font-size:9px;color:#7e88b3;margin-top:8px}.app-body{margin-left:220px;min-height:100dvh;display:flex;flex-direction:column}.topbar{height:66px;flex:none;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 32px;border-bottom:1px solid #f1f2f5}.breadcrumbs{display:flex;align-items:center;gap:8px;color:#687084;font-size:11px}.breadcrumbs span:last-child{color:#454d60}.topbar-actions{display:flex;align-items:center;gap:15px}.topbar time{font-size:11px;color:#727b8f}.avatar{height:28px;width:28px;display:flex;align-items:center;justify-content:center;font-size:10px;border-radius:50%;color:#5360ba;background:#edefff;font-weight:650}main{padding:36px 32px 24px;flex:1;min-width:0;max-width:1660px;width:100%;margin:auto}.app-footer{padding:10px 32px 20px;display:flex;justify-content:space-between;color:#929aab;font-size:10px}.menu-toggle{display:none}.notifications{position:fixed;z-index:60;top:58px;right:25px;background:white;border:1px solid #e5e7eb;padding:20px;width:380px;max-width:calc(100vw - 24px);max-height:75vh;overflow:auto;border-radius:12px;box-shadow:0 12px 30px #13192718}.notification{display:flex;flex-direction:column;text-align:left;width:100%;padding:13px 10px;border:0;border-bottom:1px solid #eef0f4;background:white;font-size:12px;color:#454d60;gap:6px}.notification.unread{background:#f4f5ff}.notification small{font-size:10px;color:#8c93a4}.sidebar-backdrop{position:fixed;inset:0;z-index:39;background:#13192760;border:0}
 @media(max-width:1050px){main{padding:28px 22px}.topbar{padding:0 22px}.topbar time{font-size:10px}.topbar-actions{gap:7px}}
 @media(max-width:760px){.sidebar{transform:translateX(-100%);transition:transform .15s}.sidebar.open{transform:translateX(0)}.app-body{margin-left:0}.menu-toggle{display:inline-flex}.topbar{padding:0 16px;height:60px}.topbar time{display:none}main{padding:24px 16px}.app-footer{padding:10px 16px 18px}.topbar-actions{gap:6px}}
</style>
